impl<F, G> Map<F, G> {
    fn new(inner: F, map: G) -> Self {
        Self {
            inner: Box::pin(inner),
            map: Some(map),
        }
    }
}

impl<F, G, U> Future for Map<F, G>
where
    F: Future,
    G: FnOnce(F::Output) -> U + Unpin,
{
    type Output = U;

    fn poll(
        self: Pin<&mut Self>,
        context: &mut Context<'_>,
    ) -> Poll<U> {
