use std::collections::HashMap;
use std::sync::Arc;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct Symbol(usize);

struct Interner {
    by_text: HashMap<Arc<str>, Symbol>,
    texts: Vec<Arc<str>>,
}

impl Interner {
    fn new() -> Self {
        Self { by_text: HashMap::new(), texts: Vec::new() }
    }

    fn intern(&mut self, text: &str) -> Symbol {
        if let Some(&symbol) = self.by_text.get(text) {
            return symbol;
        }
        let symbol = Symbol(self.texts.len());
        let owned: Arc<str> = Arc::from(text);
        self.texts.push(Arc::clone(&owned));
        self.by_text.insert(owned, symbol);
        symbol
    }

    fn resolve(&self, symbol: Symbol) -> Option<&str> {
        self.texts.get(symbol.0).map(AsRef::as_ref)
    }

    fn shared_text(&self, symbol: Symbol) -> Option<Arc<str>> {
        self.texts.get(symbol.0).cloned()
    }
}

fn main() {
    let mut interner = Interner::new();
    let first = interner.intern("parser");
    let second = interner.intern("parser");
    let third = interner.intern("scheduler");
    assert_eq!(first, second);
    assert_ne!(first, third);
    assert_eq!(interner.resolve(first), Some("parser"));
    let retained = interner.shared_text(first).unwrap();
    drop(interner);
    assert_eq!(&*retained, "parser");
}

use std::hint::black_box;
use std::time::{Duration, Instant};

fn iterator_sum(values: &[u64]) -> u64 {
    values.iter().copied()
        .filter(|value| value & 1 == 0)
        .fold(0, u64::wrapping_add)
}

fn loop_sum(values: &[u64]) -> u64 {
    let mut sum = 0_u64;
    for &value in values {
        if value & 1 == 0 {
            sum = sum.wrapping_add(value);
        }
    }
    sum
}

fn measure(operation: fn(&[u64]) -> u64, input: &[u64]) -> Duration {
    let start = Instant::now();
    let mut result = 0_u64;
    for _ in 0..64 {
        result ^= operation(black_box(input));
        black_box(result);
    }
    start.elapsed()
}

fn median(mut samples: Vec<Duration>) -> Duration {
    samples.sort();
    samples[samples.len() / 2]
}

fn main() {
    let input: Vec<u64> = (0..2_000).collect();
    assert_eq!(iterator_sum(&input), loop_sum(&input));
    for _ in 0..4 {
        black_box(iterator_sum(black_box(&input)));
        black_box(loop_sum(black_box(&input)));
    }
    let mut iterator = Vec::new();
    let mut explicit = Vec::new();
    for round in 0..11 {
        if round & 1 == 0 {
            iterator.push(measure(iterator_sum, &input));
            explicit.push(measure(loop_sum, &input));
        } else {
            explicit.push(measure(loop_sum, &input));
            iterator.push(measure(iterator_sum, &input));
        }
    }
    println!("iterator median {:?}", median(iterator));
    println!("loop median {:?}", median(explicit));
}

