use std::sync::mpsc::sync_channel;
use std::thread;

#[derive(Debug, Default)]
struct Summary {
    completed: usize,
    job_failures: usize,
    sum: u64,
    sum_overflowed: bool,
}

fn run(jobs: u64, worker_count: usize)
    -> Result<Summary, &'static str>
{
    if worker_count == 0 {
        return Err("at least one worker is required");
    }
    thread::scope(|scope| {
        let (result_tx, result_rx) = sync_channel::<Option<u64>>(8);
        let collector = scope.spawn(move || {
            let mut summary = Summary::default();
            for result in result_rx {
                match result {
                    Some(value) => {
                        summary.completed += 1;
                        match summary.sum.checked_add(value) {
                            Some(sum) => summary.sum = sum,
                            None => summary.sum_overflowed = true,
                        }
                    }
                    None => summary.job_failures += 1,
                }
            }
            summary
        });

        let mut senders = Vec::new();
        let mut workers = Vec::new();
        for _ in 0..worker_count {
            let (job_tx, job_rx) = sync_channel::<u64>(2);
            senders.push(job_tx);
            let output = result_tx.clone();
            workers.push(scope.spawn(move || {
                for value in job_rx {
                    let result = value.checked_mul(value);
                    if output.send(result).is_err() {
                        break;
                    }
                }
            }));
        }
        drop(result_tx);

        let mut dispatch_failed = false;
        let mut next = 0;
        for value in 0..jobs {
            if senders[next].send(value).is_err() {
                dispatch_failed = true;
                break;
            }
            next = (next + 1) % worker_count;
        }
        drop(senders);

        let worker_panics: Vec<_> = workers.into_iter()
            .filter_map(|worker| worker.join().err())
            .collect();
        let summary = collector.join()
            .map_err(|_| "collector panicked")?;
        if dispatch_failed || !worker_panics.is_empty() {
            Err("worker failed before pipeline completion")
        } else {
            Ok(summary)
        }
    })
}

fn main() {
    let summary = run(10, 3).unwrap();
    assert_eq!(summary.completed, 10);
    assert_eq!(summary.job_failures, 0);
    assert_eq!(summary.sum, 285);
    assert!(!summary.sum_overflowed);
}

#[derive(Debug, PartialEq, Eq)]
enum Frame {
    Offer(u16),
    Data { sequence: u32, payload: Vec<u8> },
    Close,
}

#[derive(Debug)]
struct Negotiating {
    offers: usize,
}

#[derive(Debug)]
struct Established {
    next_sequence: u32,
}

#[derive(Debug)]
struct Closed;

#[derive(Debug)]
struct Connection<S> {
    transcript: Vec<Frame>,
    state: S,
}

#[derive(Debug, PartialEq, Eq)]
enum SendError {
    PayloadTooLarge,
    SequenceExhausted,
}

impl Connection<Negotiating> {
    fn new() -> Self {
        Self {
            transcript: Vec::new(),
            state: Negotiating { offers: 0 },
        }
    }

    fn negotiate(mut self, version: u16)
        -> Result<Connection<Established>, Self>
    {
        self.state.offers += 1;
        self.transcript.push(Frame::Offer(version));
        if version != 1 {
            return Err(self);
        }
        Ok(Connection {
            transcript: self.transcript,
            state: Established { next_sequence: 0 },
        })
    }
}

impl Connection<Established> {
    fn send(&mut self, payload: Vec<u8>)
        -> Result<u32, (SendError, Vec<u8>)>
    {
        if payload.len() > 1024 {
            return Err((SendError::PayloadTooLarge, payload));
        }
        let sequence = self.state.next_sequence;
        let Some(next) = sequence.checked_add(1) else {
            return Err((SendError::SequenceExhausted, payload));
        };
        self.transcript.push(Frame::Data { sequence, payload });
        self.state.next_sequence = next;
        Ok(sequence)
    }

    fn close(mut self) -> Connection<Closed> {
        self.transcript.push(Frame::Close);
        Connection { transcript: self.transcript, state: Closed }
    }
}

impl Connection<Closed> {
    fn transcript(&self) -> &[Frame] {
        &self.transcript
    }
}

fn main() {
    let negotiating = Connection::new();
    let negotiating = negotiating.negotiate(2).unwrap_err();
    let mut ready = negotiating.negotiate(1).unwrap();
    assert_eq!(ready.send(vec![10, 20]), Ok(0));
    let closed = ready.close();
    assert_eq!(closed.transcript().len(), 4);
    assert_eq!(closed.transcript().last(), Some(&Frame::Close));
}

#[derive(Debug, PartialEq, Eq)]
enum Request {
    Queued { id: u64, body: Vec<u8> },
    Running { id: u64, body: Vec<u8> },
    Done { id: u64, status: u16 },
}

impl Request {
    fn start(self) -> Result<Self, Self> {
        match self {
            Self::Queued { id, body } => {
                Ok(Self::Running { id, body })
            }
            other => Err(other),
        }
    }

    fn finish(self, status: u16) -> Result<Self, Self> {
        match self {
            Self::Running { id, .. } => {
                Ok(Self::Done { id, status })
            }
            other => Err(other),
        }
    }
}

fn main() {
    let request = Request::Queued { id: 7, body: vec![1, 2] };
    let running = request.start().unwrap();
    let done = running.finish(200).unwrap();
    assert_eq!(done, Request::Done { id: 7, status: 200 });
    assert!(done.start().is_err());
}

#![cfg_attr(not(feature = "std"), no_std)]

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LengthError {
    PayloadTooLarge,
    AddressSpaceOverflow,
}

pub fn encoded_length(payload_len: usize)
    -> Result<usize, LengthError>
{
    if u32::try_from(payload_len).is_err() {
        return Err(LengthError::PayloadTooLarge);
    }
    let length = payload_len.checked_add(4)
        .ok_or(LengthError::AddressSpaceOverflow)?;
    #[cfg(feature = "trace")]
    {
        use std::io::Write;
        let _ = writeln!(std::io::stderr(), "encoded length {length}");
    }
    Ok(length)
}

#[derive(Debug, PartialEq, Eq)]
enum TransferError {
    InvalidAccount,
    SameAccount,
    InsufficientFunds,
    DestinationOverflow,
}

fn transfer(balances: &mut [u64], from: usize,
            to: usize, amount: u64)
    -> Result<(), TransferError>
{
    if from == to {
        return Err(TransferError::SameAccount);
    }
    let source = *balances.get(from)
        .ok_or(TransferError::InvalidAccount)?;
    let destination = *balances.get(to)
        .ok_or(TransferError::InvalidAccount)?;
    let new_source = source.checked_sub(amount)
        .ok_or(TransferError::InsufficientFunds)?;
    let new_destination = destination.checked_add(amount)
        .ok_or(TransferError::DestinationOverflow)?;
    balances[from] = new_source;
    balances[to] = new_destination;
    Ok(())
}

fn main() {
    let mut balances = [50, 10];
    transfer(&mut balances, 0, 1, 20).unwrap();
    assert_eq!(balances, [30, 30]);
    let before = balances;
    assert_eq!(transfer(&mut balances, 0, 1, 100),
        Err(TransferError::InsufficientFunds));
    assert_eq!(balances, before);
    let mut overflow = [1, u64::MAX];
    assert_eq!(transfer(&mut overflow, 0, 1, 1),
        Err(TransferError::DestinationOverflow));
    assert_eq!(overflow, [1, u64::MAX]);
}

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

#[derive(Default)]
struct Cache {
    values: Mutex<BTreeMap<String, Arc<String>>>,
}

impl Cache {
    fn get_or_load<F>(&self, key: &str, load: F) -> Arc<String>
    where
        F: FnOnce() -> String,
    {
        let existing = {
            let guard = self.values.lock().unwrap();
            guard.get(key).cloned()
        };
        if let Some(value) = existing {
            return value;
        }
        let candidate = Arc::new(load());
        let mut guard = self.values.lock().unwrap();
        Arc::clone(guard.entry(key.to_owned()).or_insert(candidate))
    }
}

fn main() {
    let cache = Cache::default();
    let first = cache.get_or_load("mode", || "fast".into());
    let second = cache.get_or_load("mode", || panic!("unused"));
    assert!(Arc::ptr_eq(&first, &second));
    assert_eq!(first.as_str(), "fast");
}
